      if (!this.open) return;
      // get view info
      const viewerPose = frame.getViewerPose(this.localSpace);
      const transform = viewerPose.transform;
      // set view info
      this.view = {
        position: [transform.position.x, transform.position.y, transform.position.z],
        quaternion: [transform.orientation.w, transform.orientation.y, transform.orientation.x, transform.orientation.z]
      };
